import{z as A,x as B,o as s,c as d,q as l,j as o,D as t,d as E,s as i,S as n,b as e}from"./chunks/framework.C8m1ZpeB.js";const C=JSON.parse('{"title":"DASH / HLS","description":"","frontmatter":{"title":"DASH / HLS","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/dash-hls.md","filePath":"cs/dash-hls.md","lastUpdated":1791063341000}'),p={name:"cs/dash-hls.md"};function T(h,a,D,P,m,u){const r=B("Mermaid");return s(),d("div",null,[a[2]||(a[2]=l('<h1 id="dash-hls" tabindex="-1">DASH / HLS <a class="header-anchor" href="#dash-hls" aria-label="Permalink to &quot;DASH / HLS&quot;">​</a></h1><div class="epigraph"><p>把视频切成片段，用清单列出多码率 URL；播放器用 HTTP GET 拉片，中间是普通缓存，而不是一条永不结束的媒体 TCP。</p><footer>—— 据 ISO/IEC 23009 DASH；RFC 8216 HLS 整理</footer></div><p><a href="/cs/http">HTTP</a> 与 <a href="/cs/cdn-intuition">CDN</a> 已能缓存 GET。<a href="/cs/stun-turn">上一课</a> 是实时通话。缺口是<strong>点播/直播切片</strong>：MPD/m3u8、分片、与 WebRTC 对照。本课不把 ABR 算法写完。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>RTSP/RTP 难穿缓存与企业代理。DASH/HLS：编码多个 bitrate 的短文件（2–10 s），清单描述时间线。播放器按清单 GET，CDN 当静态对象。直播把清单滑窗。与 SSE：都是 HTTP，SSE 是事件，这里是媒体文件。H3 可拉片，0-RTT 适合幂等 GET。</p><p><span class="marginnote">直觉类比：整部电影当一个大文件是&quot;整箱托运&quot;，中途断网前功尽弃；切片是把货拆成 2–10 秒一箱的标准件——哪箱丢了重发哪箱，路况差时还能整体换低码率的小车继续送。</span></p><p>不要把切片写成 MPEG 压缩课。</p><p><span class="marginnote">HLS RFC 8216。DASH 是 ISO。本课钉分发，不钉编码器。</span></p><h3 id="清单加-http-分片" tabindex="-1">清单加 HTTP 分片 <a class="header-anchor" href="#清单加-http-分片" aria-label="Permalink to &quot;清单加 HTTP 分片&quot;">​</a></h3><p>CDN 当静态对象缓存。直播滑窗。延迟由分片时长与缓冲决定，不是物理传播。Progressive 单文件失去 ABR。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>画：清单 → 选表示 → GET 分片。对照 WebRTC 推流。与巨帧无关直接；分片大小影响请求率和 ABR。</p>',12)),(s(),o(n,null,{default:t(()=>[i(r,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20MAN%5B%22%E6%B8%85%E5%8D%95%20MPD%2Fm3u8%22%5D%20--%3E%20BR%5B%22%E5%A4%9A%E7%A0%81%E7%8E%87%22%5D%0A%20%20BR%20--%3E%20GET%5B%22HTTP%20GET%20%E5%88%86%E7%89%87%22%5D%0A%20%20GET%20--%3E%20CDN%5B%22%E5%8F%AF%E7%BC%93%E5%AD%98%E5%AF%B9%E8%B1%A1%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[E(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("h2",{id:"机制",tabindex:"-1"},[E("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=e("p",null,"GeoDNS 找近边缘。Cookie 可用于鉴权 URL。队头：H1 多连接拉片；H2 多流。PMTUD 影响分片下载。DRM 在分片上，点名。",-1)),a[5]||(a[5]=e("p",null,[e("span",{class:"marginnote"},'初学者容易以为视频网站有一条"专用视频通道"。实际每个分片就是一次普通 HTTP GET，CDN 把它当静态文件缓存——百万观众看的往往是同一批边缘副本，这正是选 HTTP 而非专用流协议的核心理由。')],-1)),a[6]||(a[6]=e("p",null,"直播延迟 ≈ 分片时长 × 缓冲片数，不是卫星那种物理。",-1)),(s(),o(n,null,{default:t(()=>[i(r,{id:"mermaid-47",class:"mermaid",graph:"flowchart%20TD%0A%20%20ENC%5B%22%E7%BC%96%E7%A0%81%E5%99%A8%E6%8C%81%E7%BB%AD%E4%BA%A7%E7%89%87%22%5D%20--%3E%20MAN%5B%22%E6%B8%85%E5%8D%95%E6%BB%91%E7%AA%97%EF%BC%9A%E5%8F%AA%E5%88%97%E6%9C%80%E8%BF%91%E5%87%A0%E7%89%87%22%5D%0A%20%20MAN%20--%3E%20OLD%5B%22%E6%97%A7%E5%88%86%E7%89%87%E6%BB%91%E5%87%BA%E7%AA%97%E5%8F%A3%E5%B9%B6%E4%B8%8B%E7%BA%BF%22%5D%0A%20%20MAN%20--%3E%20PL%5B%22%E6%92%AD%E6%94%BE%E5%99%A8%E6%8B%89%E5%8F%96%E6%B8%85%E5%8D%95%EF%BC%8CGET%20%E6%9C%80%E6%96%B0%E7%89%87%22%5D%0A%20%20PL%20--%3E%20BUF%5B%22%E6%9C%AC%E5%9C%B0%E7%BC%93%E5%86%B2%E8%8B%A5%E5%B9%B2%E7%A7%92%22%5D%0A%20%20BUF%20--%3E%20PLAY%5B%22%E8%BE%B9%E6%92%AD%E8%BE%B9%E7%BB%AD%E6%8B%89%E4%B8%8B%E4%B8%80%E7%89%87%22%5D%0A%20%20PLAY%20--%3E%20PL%0A"})]),fallback:t(()=>[...a[1]||(a[1]=[E(" Loading... ",-1)])]),_:1})),a[7]||(a[7]=l('<p><span class="marginnote">数字实例：分片 6 秒、缓冲 3 片，直播延迟约 \\(6\\times 3=18\\) 秒起步。想压到几秒内，得换更短的分片或 LL-HLS 一类分块传输——这是清单与缓冲策略的事，不是&quot;网速慢&quot;。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入 CMAF 的全部。ABR 自适应码率是下一课。后课默认：自适应流 = 清单 + HTTP 分片 + 缓存。</p><p>把整部电影当一个文件 Progressive Download 失去 ABR 与缓存粒度。</p><p>下一课<a href="/cs/abr-streaming">ABR 自适应码率</a>。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>分片 + 清单，走标准 HTTP。</li><li>CDN 友好；直播滑窗清单。</li><li>延迟由分片和缓冲策略决定。</li><li>后课只引用本课钉死的对象，不从该领域总问题重开。</li><li>出处：ISO DASH；RFC 8216。</li></ul>',7))])}const H=A(p,[["render",T]]);export{C as __pageData,H as default};
